13		"github.com/anthnel/devdesk/internal/git"
14		"github.com/anthnel/devdesk/internal/patch"
15		"github.com/anthnel/devdesk/internal/remediation"
16		"github.com/anthnel/devdesk/internal/scan"
17	)
18	
19	// The change a built-in fix would make (DEVDESK-753). One computation feeds the
20	// preview and the confirmation of ctrl+o, so what is shown is what is written.
21	
22	// reasonPreviewStale is why a fix is refused on a file written after the scan:
23	// the lines the scan reported may no longer be the lines of the file.
24	const reasonPreviewStale = "The file changed after the scan — re-scan to preview the fix"
25	
26	// misconfigChange is the fix as it would land: the pure product shared by the
27	// preview and ctrl+o.
28	type misconfigChange struct {
29		// File is the slash path, relative to the target, of the file the fix edits.
30		File string
31		// Lines is the formatted diff, sanitized, uncapped and uncut.
32		Lines []string
33		// Updated is the exact bytes ctrl+o writes.
34		Updated []byte
35		Scope   remediation.Scope
36	}
37	
38	// misconfigChangeOf is the pure part of the computation: no I/O. It returns a
39	// reason when the rule declines, and an error when the rewrite fails.
40	func misconfigChangeOf(rule remediation.Rule, rel string, original []byte, f scan.Finding) (misconfigChange, string, error) {
41		edits, reason := rule.Fix(original, f)
42		if reason != "" {
43			return misconfigChange{}, reason, nil
44		}
45		updated, err := patch.Rewrite(original, edits)
46		if err != nil {
47			return misconfigChange{}, "", fmt.Errorf("%s: %w", rel, err)
48		}
49		diff, err := patch.Diff(rel, original, edits)
50		if err != nil {
51			return misconfigChange{}, "", fmt.Errorf("%s: %w", rel, err)
52		}
53		return misconfigChange{
54			File: rel, Lines: changeLines(diff), Updated: updated,
55			Scope: rule.ScopeOf(updated, edits),
56		}, "", nil
57	}
58	
59	// changeLines formats a patch.Diff for display: the two header lines are
60	// dropped (the file is named elsewhere), a hunk marker is indented by two spaces
61	// so every line starts with +, - or a space, and each line is made safe for the
62	// terminal. Nothing is capped or cut.
63	//
64	// Only the first two lines can be headers: a removed line "-- x" reads "--- x"
65	// further down and is a change.
66	func changeLines(diff string) []string {
67		lines := strings.Split(diff, "\n")
68		if lines[len(lines)-1] == "" {
69			lines = lines[:len(lines)-1]
70		}
71		if len(lines) >= 2 && strings.HasPrefix(lines[0], "--- ") && strings.HasPrefix(lines[1], "+++ ") {
72			lines = lines[2:]
73		}
74		if len(lines) == 0 {
75			return nil
76		}
77		out := make([]string, len(lines))
78		for i, l := range lines {
79			if strings.HasPrefix(l, "@@") {
80				l = "  " + l
81			}
82			out[i] = withoutControlSpace(l)
83		}
84		return out
85	}
86	
87	// previewStale says whether a file written at modTime changed after the scan
88	// that ended at scannedAt. A time that is not known cannot make a file stale.
89	func previewStale(modTime, scannedAt time.Time) bool {
90		return !modTime.IsZero() && !scannedAt.IsZero() && modTime.After(scannedAt)
91	}
92	
93	// previewFailure words an error for the screen, never showing err.Error()
94	// (Rule 128): the file is named, the detail is in the log.
95	func previewFailure(rel string, err error) string {
96		switch {
97		case errors.Is(err, fs.ErrNotExist):
98			return rel + " no longer exists"
99		case errors.Is(err, fs.ErrPermission):
100			return rel + " cannot be read"
101		default:
102			return "the fix could not be computed — check logs"
103		}
104	}
105	
106	// resolveInside is the absolute path of file under target and its slash path
107	// relative to target, or the reason it is refused: the path leaves the target
108	// lexically, or a link on the way leads out of it. Nothing is read.
109	func resolveInside(target, file string) (path, rel, reason string) {
110		path, a := findingFilePath(scan.Finding{File: file}, target, true)
111		if !a.Enabled() {
112			return "", "", a.Reason
113		}
114		if !staysInside(target, path) {
115			return "", "", reasonFileLinkOutsideTarget
116		}
117		r, err := filepath.Rel(filepath.Clean(target), path)
118		if err != nil {
119			return "", "", reasonFileOutsideTarget
120		}
121		return path, filepath.ToSlash(r), ""
122	}
123	
124	// staleOn is a stat failure or a decline when the file at path was written after
125	// the scan.
126	func staleOn(path, rel string, scannedAt time.Time) error {
127		info, err := os.Stat(path)
128		if err != nil {
129			return fmt.Errorf("%s: %w", rel, err)
130		}
131		if previewStale(info.ModTime(), scannedAt) {
132			return errDeclined{reasonPreviewStale}
133		}
134		return nil
135	}
136	
137	// computeMisconfigFix is the I/O side of the fix, shared by the Cmd ctrl+o starts
138	// and by anything else that wants the same answer: the path is checked (lexically,
139	// then through links), the files are measured against the end of the scan, and
140	// only then is the edited file read. scannedAt is the end time of the result on
141	// screen; the zero time never makes a file stale.
142	func computeMisconfigFix(target string, f scan.Finding, scannedAt time.Time) MisconfigFixPreparedMsg {
143		fail := func(err error) MisconfigFixPreparedMsg {
144			return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
145		}
146		decline := func(reason string) MisconfigFixPreparedMsg { return fail(errDeclined{reason}) }
147	
148		rule, ok := remediation.FixFor(f)
149		if !ok {
150			return decline(noFixReason(f))
151		}
152		// A rule that edits another file than the finding's reads the finding's own
153		// to find it, so that one is checked before the rule is asked.
154		findingPath := ""
155		if rule.Target != nil {
156			var reason string
157			if findingPath, _, reason = resolveInside(target, f.File); reason != "" {
158				return decline(reason)
159			}
160		}
161		edited, reason := rule.FileFor(target, f)
162		if reason != "" {
163			return decline(reason)
164		}
165		path, rel, reason := resolveInside(target, edited)
166		if reason != "" {
167			return decline(reason)
168		}
169		if err := staleOn(path, rel, scannedAt); err != nil {
170			return fail(err)
171		}
172		if findingPath != "" && findingPath != path {
173			if err := staleOn(findingPath, f.File, scannedAt); err != nil {
174				return fail(err)
175			}
176		}
177		original, err := readFile(path)
178		if err != nil {
179			return fail(err)
180		}
181		change, reason, err := misconfigChangeOf(rule, rel, original, f)
182		if err != nil {
183			return fail(err)
184		}
185		if reason != "" {
186			return decline(reason)
187		}
188		file := preparedWrite{File: rel, Path: path, Original: original, Updated: change.Updated}
189		if file.State, err = git.StateOf(path); err != nil {
190			log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
191			file.StateErr = true
192		}
193		body := rule.Title + "\n\n"
194		if rule.Warning != "" {
195			body += "Warning: " + rule.Warning + "\n\n"
196		}
197		return MisconfigFixPreparedMsg{
198			Target: target, File: file, FindingFile: f.File,
199			Rule: f.ID, Instance: instanceOf(f), Body: body + strings.Join(change.Lines, "\n") + "\n",
200			Scope: change.Scope, Lines: change.Lines,
201		}
202	}
