		"GIT_CONFIG_GLOBAL":   empty,
		"GIT_CONFIG_SYSTEM":   empty,
		"GIT_CONFIG_NOSYSTEM": "1",
		"HOME":                dir,
		"USERPROFILE":         dir,
		"XDG_CONFIG_HOME":     dir,
	} {
		if err := os.Setenv(k, v); err != nil {
			fmt.Fprintf(os.Stderr, "setting %s: %v\n", k, err)
			return 1
		}
	}
