package security

import (
	"bytes"
	"errors"
	"io/fs"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/patch"
	"github.com/anthnel/devdesk/internal/remediation"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-753, step 1 (AC1, AC2): the fix as it would land is computed once, and
// the preview and the confirmation read that one product. Nothing here touches
// the real HOME, the keyring or a process: each test works in t.TempDir() and
// feeds Update by hand (feed drops Cmds, so the preparation Cmd is run with run).

// ── The fixtures are the catalog ─────────────────────────────────────────────

// A rule added to the catalog without a fixture fails here, not silently.
	return fixtures
}

// writeTree writes files under dir and gives each the modification time at, so a
// test never depends on the clock of the machine running it.
func writeTree(t *testing.T, dir string, files map[string]string, at time.Time) {
	t.Helper()
	for name, content := range files {
		path := filepath.Join(dir, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
		touch(t, path, at)
	}
}

// touch sets the modification time of path (following a link).
func touch(t *testing.T, path string, at time.Time) {
	t.Helper()
	if err := os.Chtimes(path, at, at); err != nil {
		t.Fatal(err)
	}
}

// readTree reads the file name under dir.
func readTree(t *testing.T, dir, name string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(name)))
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// scannedAtFixed is the instant the fixtures' scans ended. Files are given times
// around it with os.Chtimes.
var scannedAtFixed = time.Date(2026, 11, 20, 12, 0, 0, 0, time.UTC)

// changeModel opens the Misconfigurations tab on dir with the one finding, in a
// result whose scan ended at endedAt (the zero time: unknown).
func changeModel(t *testing.T, dir string, f scan.Finding, endedAt time.Time) Model {
	t.Helper()
	result := &scan.Result{
		Target: dir, TargetType: scan.TargetDirectory, Findings: []scan.Finding{f},
		StartTime: endedAt.Add(-time.Minute), EndTime: endedAt,
	}
	if endedAt.IsZero() {
		result.StartTime = time.Time{}
	}
	m := feed(t, NewWithPreloadedResult(testConfig(), nil, result), tea.WindowSizeMsg{Width: 160, Height: 30})
	for range TabMisconfig {
		m = feed(t, m, testutil.Key("tab"))
	}
	return m
}

// previewed presses the write key and runs the Cmd it returns, which is the
// computation the preview and the confirmation share. It returns the message the
// Cmd answered with and the model that has read it.
func previewed(t *testing.T, m Model) (Model, MisconfigFixPreparedMsg) {
	t.Helper()
	m, cmd := step(t, m, testutil.Key(writeRemediationKey))
	if cmd == nil {
		t.Fatalf("the write key started nothing; footer: %q", m.footer.Text())
	}
	msg, ok := run(t, cmd).(MisconfigFixPreparedMsg)
	if !ok {
		t.Fatalf("the write key did not answer with a MisconfigFixPreparedMsg")
	}
	return feed(t, m, msg), msg
}

// fixtureOnDisk writes the fixture under a fresh directory, every file stamped
// before the scan, and returns the directory.
func fixtureOnDisk(t *testing.T, fx changeFixture) string {
	t.Helper()
	dir := t.TempDir()
	writeTree(t, dir, fx.files, scannedAtFixed.Add(-time.Hour))
	return dir
}

// ruleOf is the catalog rule of a fixture.
func ruleOf(t *testing.T, fx changeFixture) remediation.Rule {
	t.Helper()
	rule, ok := remediation.FixFor(fx.finding)
	if !ok {
		t.Fatalf("%s: the catalog has no rule for the fixture's finding", fx.id)
	}
	return rule
}
func TestComputeMisconfigFixCarriesTheChangeOfEveryRule(t *testing.T) {
	for _, fx := range changeFixtures(t) {
		t.Run(fx.id, func(t *testing.T) {
			dir := fixtureOnDisk(t, fx)
			msg := computeMisconfigFix(dir, fx.finding, time.Time{})
			if msg.Err != nil {
				t.Fatalf("error: %v", msg.Err)
			}
			rule := ruleOf(t, fx)
			change, _, _ := misconfigChangeOf(rule, fx.edited, []byte(fx.files[fx.edited]), fx.finding)
			if len(msg.Lines) == 0 || !slices.Equal(msg.Lines, change.Lines) {
				t.Errorf("Lines = %q, want %q", msg.Lines, change.Lines)
			}
			if msg.File.File != fx.edited || !bytes.Equal(msg.File.Updated, change.Updated) {
				t.Errorf("File = %q, %d bytes; want %q, %d bytes", msg.File.File, len(msg.File.Updated), fx.edited, len(change.Updated))
			}
			if string(msg.File.Original) != fx.files[fx.edited] {
				t.Errorf("Original is not the file as it was read")
			}
			if msg.FindingFile != fx.finding.File || msg.Rule != fx.finding.ID {
				t.Errorf("FindingFile, Rule = %q, %q; want %q, %q", msg.FindingFile, msg.Rule, fx.finding.File, fx.finding.ID)
			}
			// The body is the title, the warning, then the same lines.
			if !strings.Contains(msg.Body, strings.Join(change.Lines, "\n")) {
				t.Errorf("the body does not hold the preview lines:\n%s", msg.Body)
			}
			if !strings.HasPrefix(msg.Body, rule.Title) {
				t.Errorf("the body does not start with the rule's title %q:\n%s", rule.Title, msg.Body)
			}
			if rule.Warning != "" && !strings.Contains(msg.Body, "Warning: "+rule.Warning) {
				t.Errorf("the body lost the rule's warning:\n%s", msg.Body)
			}
			for _, h := range []string{"--- " + fx.edited, "+++ " + fx.edited} {
				if strings.Contains(msg.Body, h) {
					t.Errorf("the body still carries the diff header %q:\n%s", h, msg.Body)
				}
			}
		})
	}
}

func TestComputeMisconfigFixOfADecliningRuleHasAReasonAndNoLines(t *testing.T) {
	fx := dockerfileFixture("AVD-DS-0029", "FROM debian:12\nRUN apt-get install --no-install-recommends -y curl\n", 2, 2)
	dir := fixtureOnDisk(t, fx)
	msg := computeMisconfigFix(dir, fx.finding, time.Time{})
	var d errDeclined
	if !errors.As(msg.Err, &d) || d.reason != remediation.ReasonAlreadyFixed {
		t.Fatalf("Err = %v, want a decline: %q", msg.Err, remediation.ReasonAlreadyFixed)
	}
	if len(msg.Lines) != 0 || msg.Body != "" {
		t.Errorf("a decline carries %d lines and a body %q", len(msg.Lines), msg.Body)
	}
}

// ── AC2: what the modal shows is what is written ─────────────────────────────

// diffRows counts the lines that read as part of a diff.
func diffRows(lines []string) int {
}

// A link that leaves the target is refused with its reason; nothing outside is
// read or written.
func TestALinkThatLeavesTheTargetIsRefusedByThePreviewWithItsReason(t *testing.T) {
	fx := fixtureFor(t, "AVD-DS-0021")
	target, outside := outsideTree(t)
	symlink(t, filepath.Join(outside, "Dockerfile"), filepath.Join(target, "Dockerfile"))
	before := readTree(t, outside, "Dockerfile")

	m, cmd := step(t, changeModel(t, target, fx.finding, scannedAtFixed), testutil.Key("enter"))
	msg, ok := run(t, cmd).(ChangePreviewMsg)
	if !ok {
		t.Fatal("no preview was computed")
	}
	if len(msg.Prepared.File.Original) != 0 {
		t.Error("the file behind the link was read")
	}
	m = feed(t, m, msg)

	if m.changePreview.State != previewDeclined {
		t.Errorf("state = %v, want declined", m.changePreview.State)
	}
	if a := m.canFixMisconfig(); a.Enabled() || a.Reason != reasonFileLinkOutsideTarget {
		t.Errorf("canFixMisconfig = %+v, want %q", a, reasonFileLinkOutsideTarget)
	}
	if got := m.fixStatus(fx.finding).Label(); got != labelBuiltInUnavailable+": "+reasonFileLinkOutsideTarget {
		t.Errorf("the Fix line reads %q", got)
	}
	if block := changeBlock(m); !slices.Equal(block, []string{"Change: none: DevDesk cannot write this fix"}) {
		t.Errorf("the section reads %q", block)
	}
	if got := readTree(t, outside, "Dockerfile"); got != before {
		t.Errorf("the file outside the target changed:\n%s", got)
	}
}

// ── Step 4: the stored verdict ───────────────────────────────────────────────

// Rule 130: the column of keys is the same in every state of the preview; what
// changes is Disabled, and only ctrl+o moves.
}

// requireReadable skips a test that needs a file the process cannot read.
func requireUnreadableFiles(t *testing.T) {
	t.Helper()
	if runtime.GOOS == "windows" || os.Geteuid() == 0 {
		t.Skip("file permissions are not enforced for this user")
	}
}

// previewScenes are the five states a stored preview can be in.
func previewScenes(t *testing.T) map[string]previewScene {
	t.Helper()
	return map[string]previewScene{
		"pending":  openPreview(t, ds0002(t), -time.Hour),
		"ready":    readyScene(t),
		"expired":  expiredScene(t),
		"declined": declinedScene(t),
		"failed":   failedScene(t),
	}
}

// ── Step 3: the Cmd, and who starts it ───────────────────────────────────────

